import React, { useState, useEffect } from 'react';
import axios from 'axios';

export default function ManageClasses() {
  const [classes, setClasses] = useState([]);
  const [formData, setFormData] = useState({ day: '', grade: '', subject: '', time_slot: '', teacher: '' });

  useEffect(() => { axios.get('http://localhost:8081/api/timetable').then(res => setClasses(res.data)); }, []);

  const handleSubmit = (e) => {
    e.preventDefault();
    axios.post('http://localhost:8081/api/timetable', formData).then(() => {
        window.location.reload(); // පන්ති ඇඩ් කළාම පේජ් එක රීලෝඩ් වෙනවා
    });
  };

  return (
    <div>
      <h2>Manage Classes</h2>
      <form onSubmit={handleSubmit}>
        <input placeholder="Day" onChange={e => setFormData({...formData, day: e.target.value})} required />
        <input placeholder="Grade" onChange={e => setFormData({...formData, grade: e.target.value})} required />
        <input placeholder="Subject" onChange={e => setFormData({...formData, subject: e.target.value})} required />
        <input placeholder="Time" onChange={e => setFormData({...formData, time_slot: e.target.value})} required />
        <input placeholder="Teacher" onChange={e => setFormData({...formData, teacher: e.target.value})} required />
        <button type="submit">Add Class</button>
      </form>
      <table>
        {classes.map(c => <tr key={c.id}><td>{c.subject}</td><td>{c.teacher}</td></tr>)}
      </table>
    </div>
  );
}
